using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including analysis, algebra, and statistics." },
        new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and linguistic studies." },
        new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of human civilizations, events, and cultural developments." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a PhD from MIT and has 15 years of experience teaching introductory CS courses. Her research focuses on CS education and programming language design.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an award-winning educator specializing in algorithm design. He previously worked at Google Research.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Code = "CS 350", Title = "Operating Systems", Description = "Principles of operating system design including process management, memory management, file systems, and concurrency.", Credits = 4, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez contributed to the Linux kernel and brings real-world systems experience to the classroom.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Code = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Whitfield", InstructorBio = "Dr. Whitfield has published extensively on mathematical pedagogy and real analysis.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 5, Code = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma's research in applied linear algebra has applications in machine learning and data science.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, Code = "MATH 310", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00–12:20 PM", InstructorName = "Dr. Alan Whitfield", InstructorBio = "Dr. Whitfield has published extensively on mathematical pedagogy and real analysis.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 7, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop effective academic writing skills through essay composition, argumentation, and rhetorical analysis.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Prof. Linda Hartley", InstructorBio = "Prof. Hartley is an accomplished author and writing coach with a focus on clear academic communication.", DepartmentId = 3, DepartmentName = "English", IsFeatured = false },
        new() { Id = 8, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial era to the present, exploring themes of identity and social change.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Kevin Okafor", InstructorBio = "Dr. Okafor specializes in 20th-century American fiction and has authored three books on the Harlem Renaissance.", DepartmentId = 3, DepartmentName = "English", IsFeatured = true },
        new() { Id = 9, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Thomas Bell", InstructorBio = "Dr. Bell is an experimental physicist whose engaging demonstrations bring physics concepts to life.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 10, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", InstructorName = "Dr. Nina Volkov", InstructorBio = "Dr. Volkov's research in photonics has led to multiple patents and industry collaborations.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "A survey of major civilizations, empires, and cultural exchanges from prehistory through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Eleanor Vance", InstructorBio = "Dr. Vance is an archaeologist and historian specializing in ancient Mediterranean civilizations.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
        new() { Id = 12, Code = "HIST 275", Title = "The Modern Era", Description = "Political, economic, and social transformations from the Industrial Revolution through the Cold War.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. Marcus Lehmann", InstructorBio = "Dr. Lehmann is a published author on 20th-century European history and has consulted for documentary films.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app this would persist to a database
        return request.CourseId > 0
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

